// CV22.DS7.US10 slice E — Pi and Codex session backfill parity.
//
// Both imports are graded as resulting database state over the committed
// fixture corpus, against `backfill.golden.json` generated by the Python
// oracle. The corpus pins the walk order (path components, not strings),
// every timestamp form, whole-file skips on corrupt or structurally invalid
// input, and the title asymmetry between the two importers.
//
// The import-vs-live-hook race (resolved decision 4B) is proven the way the
// Python fix was: a second writer holds the lock, binds the session while the
// backfill waits, and must keep its binding.

import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { copyFileSync, mkdirSync, mkdtempSync, utimesSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import test from "node:test";
import {
  backfillCodexSession,
  backfillPiSessions,
  homeBornAt,
  parsePiContent,
  parsePiTimestamp,
  resolvePiSessionsDir,
} from "#conversation/backfill.ts";
import { openDatabaseCopyForWrite, type WritableDatabase } from "#db/database.ts";
import {
  CODEX_DIR,
  frozenDeps,
  backfillGolden as golden,
  PI_SESSIONS_DIR,
  seedTrackedSession,
  snapshotState,
} from "#helpers/backfillFixture.ts";
import { createRuntimeTables } from "#helpers/runtimeSchema.ts";

/** No floor: the corpus is graded as Python graded it, every untracked session imported. */
const NO_FLOOR = "1970-01-01T00:00:00Z";

function fixture(): { db: WritableDatabase; dir: string } {
  const dir = mkdtempSync("/tmp/backfill-");
  const db = openDatabaseCopyForWrite(join(dir, "copy.db"));
  createRuntimeTables(db);
  return { db, dir };
}

// --- Pi sessions directory walk ---

test("backfillPiSessions imports the fixture corpus exactly as Python does", () => {
  const { db, dir } = fixture();
  const deps = frozenDeps();
  seedTrackedSession(db, join(PI_SESSIONS_DIR, "tracked.jsonl"), "pi");

  const count = backfillPiSessions(db, { sessionsDir: PI_SESSIONS_DIR, notBefore: NO_FLOOR }, deps);
  assert.equal(count, golden.pi_sessions.first_count);
  assert.deepEqual(snapshotState(db, PI_SESSIONS_DIR), golden.pi_sessions.state);

  // Every imported session is now tracked, so the walk is idempotent.
  assert.equal(
    backfillPiSessions(db, { sessionsDir: PI_SESSIONS_DIR, notBefore: NO_FLOOR }, deps),
    golden.pi_sessions.rerun_count,
  );
  assert.equal(
    backfillPiSessions(db, { sessionsDir: join(dir, "absent"), notBefore: NO_FLOOR }, deps),
    golden.pi_sessions.absent_dir_count,
  );
  db.close();
});

test("the Pi walk is ordered by path components: a/b.jsonl before a-x/c.jsonl", () => {
  // Pinned separately from the full snapshot so a reordering failure names
  // the property rather than dumping two states.
  const order = golden.pi_sessions.state.runtime_sessions
    .map((session) => session.session_id)
    .filter((id) => id !== "<sessions_dir>/tracked.jsonl");
  assert.deepEqual(order, [
    "<sessions_dir>/a/b.jsonl",
    "<sessions_dir>/a-x/c.jsonl",
    "<sessions_dir>/emoji-title.jsonl",
    "<sessions_dir>/nested/deeper/d.jsonl",
  ]);
  assert.ok(
    ["a-x/c.jsonl", "a/b.jsonl"].sort()[0] === "a-x/c.jsonl",
    "precondition: a string sort would reverse the first two",
  );
});

test("parsePiTimestamp reproduces every form Python accepts", () => {
  const now = () => "<now>";
  assert.equal(parsePiTimestamp(1713348000000, now), "2024-04-17T10:00:00+00:00");
  assert.equal(parsePiTimestamp(1713348000123, now), "2024-04-17T10:00:00.123000+00:00");
  assert.equal(parsePiTimestamp(1713348000123.7, now), "2024-04-17T10:00:00.123700+00:00");
  assert.equal(parsePiTimestamp("2026-04-17T10:00:00Z", now), "2026-04-17T10:00:00Z");
  // A seconds epoch is below Python's 1e10 gate; bool is an int that never
  // clears it; null and absent fall through.
  assert.equal(parsePiTimestamp(1713348000, now), "<now>");
  assert.equal(parsePiTimestamp(true, now), "<now>");
  assert.equal(parsePiTimestamp(null, now), "<now>");
  assert.equal(parsePiTimestamp(undefined, now), "<now>");
});

test("parsePiContent joins text blocks with a newline and ignores the rest", () => {
  assert.equal(parsePiContent("plain"), "plain");
  assert.equal(
    parsePiContent([
      { type: "text", text: "a" },
      { type: "tool_use", name: "x" },
      "stray",
      { type: "text" },
      { type: "text", text: "b" },
    ]),
    "a\n\nb",
  );
  assert.equal(parsePiContent(42), "");
  assert.equal(parsePiContent({ type: "text", text: "dict" }), "");
  assert.throws(() => parsePiContent([{ type: "text", text: 123 }]), TypeError);
});

test("resolvePiSessionsDir follows Python's order: argument, PI_SESSIONS_DIR, ~/.pi", () => {
  const home = "/home/navigator";
  assert.equal(
    resolvePiSessionsDir("/explicit", { PI_SESSIONS_DIR: "/from-env" }, home),
    "/explicit",
  );
  assert.equal(resolvePiSessionsDir(null, { PI_SESSIONS_DIR: "/from-env" }, home), "/from-env");
  assert.equal(resolvePiSessionsDir("", {}, home), "/home/navigator/.pi/agent/sessions");
  assert.equal(
    resolvePiSessionsDir(undefined, { PI_SESSIONS_DIR: "" }, home),
    join(home, ".pi", "agent", "sessions"),
  );
});

// --- Codex single-file imports ---

test("backfillCodexSession imports the fixture corpus exactly as Python does", () => {
  const { db } = fixture();
  const deps = frozenDeps();
  seedTrackedSession(db, "codex-tracked-0006", "codex");

  for (const scenario of golden.codex.cases) {
    const count = backfillCodexSession(
      db,
      { jsonlPath: join(CODEX_DIR, scenario.file), interface: scenario.interface },
      deps,
    );
    assert.equal(count, scenario.count, scenario.label);
  }

  // A kept event without a timestamp fails model validation in Python inside
  // the import transaction; nothing is written on either side.
  const before = db.prepare("SELECT COUNT(*) AS c FROM conversations").get()?.c;
  assert.equal(golden.codex.null_timestamp.raises, true);
  assert.throws(
    () => backfillCodexSession(db, { jsonlPath: join(CODEX_DIR, "null-timestamp.jsonl") }, deps),
    TypeError,
  );
  assert.equal(db.prepare("SELECT COUNT(*) AS c FROM conversations").get()?.c, before);
  assert.equal(golden.codex.null_timestamp.rows_unchanged, true);

  assert.deepEqual(snapshotState(db), golden.codex.state);
  db.close();
});

test("the two importers title differently, and that asymmetry is Python's", () => {
  const pi = golden.pi_sessions.state.conversations[0];
  const codex = golden.codex.state.conversations[0];
  assert.ok(pi && codex);
  // Pi: cut to 60 code points, whitespace collapsed, provenance recorded.
  assert.equal(pi.title, "How do I configure the café server for the nomad worksho");
  assert.equal(pi.metadata_raw, '{"title_source": "first_user", "title_status": "provisional"}');
  // Codex: word-boundary cut with an ellipsis, bare column write, no metadata.
  assert.equal(codex.title, "Please review the persistence layer of the port and tell me...");
  assert.equal(codex.metadata_raw, null);
});

// --- Resolved decision 4B: import vs live-hook race ---

const LOCK_HOLDER = join(import.meta.dirname, "backfillLockHolderWorker.ts");

function spawnLockHolder(
  dbPath: string,
  sessionId: string,
): Promise<{ locked: Promise<void>; done: Promise<number | null> }> {
  return new Promise((resolveSpawn) => {
    const child = spawn(process.execPath, [LOCK_HOLDER, dbPath, sessionId], {
      env: { ...process.env, NODE_OPTIONS: "--no-warnings" },
    });
    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += String(chunk);
    });
    const locked = new Promise<void>((resolveLocked, reject) => {
      child.stdout.on("data", (chunk) => {
        if (String(chunk).includes("locked")) resolveLocked();
      });
      child.on("error", reject);
    });
    const done = new Promise<number | null>((resolveDone) => {
      child.on("close", (code) => {
        if (code !== 0) console.error(`lock holder stderr: ${stderr}`);
        resolveDone(code);
      });
    });
    resolveSpawn({ locked, done });
  });
}

test("a binding won by a live hook while the import waits for the lock survives the backfill", async () => {
  const { db, dir } = fixture();
  const sessionsDir = join(dir, "sessions");
  mkdirSync(sessionsDir);
  copyFileSync(
    join(PI_SESSIONS_DIR, "nested", "deeper", "d.jsonl"),
    join(sessionsDir, "race.jsonl"),
  );
  const sessionId = join(sessionsDir, "race.jsonl");

  const holder = await spawnLockHolder(join(dir, "copy.db"), sessionId);
  await holder.locked;

  // The pre-check reads past the RESERVED lock and sees no binding; the import
  // then blocks on BEGIN IMMEDIATE until the hook commits, and must re-check.
  const count = backfillPiSessions(db, { sessionsDir, notBefore: NO_FLOOR }, frozenDeps());
  assert.equal(await holder.done, 0);

  assert.equal(count, 0);
  const session = db.prepare("SELECT * FROM runtime_sessions WHERE session_id = ?").get(sessionId);
  assert.equal(session?.conversation_id, "conv-live");
  assert.equal(session?.active, 1);
  assert.equal(session?.closed_at, null);
  assert.deepEqual(
    db
      .prepare("SELECT id FROM conversations")
      .all()
      .map((row) => row.id),
    ["conv-live"],
  );
  db.close();
});

// --- CR121: a home imports only the Pi sessions newer than itself ---

const BIRTH = "2026-06-01T00:00:00.000000Z";

function piSession(dir: string, name: string, lastMessageAt: string, mtime: Date): string {
  const path = join(dir, name);
  writeFileSync(
    path,
    [
      {
        type: "message",
        message: {
          role: "user",
          content: `hello from ${name}`,
          timestamp: "2026-01-01T00:00:00+00:00",
        },
      },
      {
        type: "message",
        message: { role: "assistant", content: "reply", timestamp: lastMessageAt },
      },
    ]
      .map((line) => JSON.stringify(line))
      .join("\n"),
  );
  utimesSync(path, mtime, mtime);
  return path;
}

function trackedSessions(db: WritableDatabase): string[] {
  return db
    .prepare("SELECT session_id FROM runtime_sessions ORDER BY session_id")
    .all()
    .map((row) => String(row.session_id));
}

test("a session that ended before the home was born is not imported; one that ended after is", () => {
  const { db, dir } = fixture();
  const sessionsDir = join(dir, "sessions");
  mkdirSync(sessionsDir);
  piSession(
    sessionsDir,
    "old.jsonl",
    "2026-05-31T23:59:59+00:00",
    new Date("2026-05-31T23:59:59Z"),
  );
  const kept = piSession(
    sessionsDir,
    "new.jsonl",
    "2026-06-02T00:00:00+00:00",
    new Date("2026-06-02T00:00:00Z"),
  );

  const count = backfillPiSessions(db, { sessionsDir, notBefore: BIRTH }, frozenDeps());
  assert.equal(count, 1);
  assert.deepEqual(trackedSessions(db), [kept]);

  // The skip is not recorded: the file is untracked, and the rule holds again.
  assert.equal(backfillPiSessions(db, { sessionsDir, notBefore: BIRTH }, frozenDeps()), 0);
  db.close();
});

test("a file last written before the birth is skipped unread, whatever it holds", () => {
  const { db, dir } = fixture();
  const sessionsDir = join(dir, "sessions");
  mkdirSync(sessionsDir);
  // Newer messages than the birth, but an mtime before it: under sane clocks
  // that cannot happen, so the pre-filter trusts the mtime and never reads.
  piSession(
    sessionsDir,
    "stale-mtime.jsonl",
    "2026-07-01T00:00:00+00:00",
    new Date("2026-05-01T00:00:00Z"),
  );

  assert.equal(backfillPiSessions(db, { sessionsDir, notBefore: BIRTH }, frozenDeps()), 0);
  assert.deepEqual(trackedSessions(db), []);
  db.close();
});

test("the mtime pre-filter is only a pre-filter: a file written after the birth is judged by its last message", () => {
  const { db, dir } = fixture();
  const sessionsDir = join(dir, "sessions");
  mkdirSync(sessionsDir);
  // Written after the birth (a copy, a sync), but the conversation ended before it.
  piSession(
    sessionsDir,
    "copied-later.jsonl",
    "2026-03-01T00:00:00+00:00",
    new Date("2026-07-01T00:00:00Z"),
  );

  assert.equal(backfillPiSessions(db, { sessionsDir, notBefore: BIRTH }, frozenDeps()), 0);
  assert.deepEqual(trackedSessions(db), []);
  db.close();
});

test("an undated session is newer, not older: it dates to now and is imported", () => {
  const { db, dir } = fixture();
  const sessionsDir = join(dir, "sessions");
  mkdirSync(sessionsDir);
  const path = join(sessionsDir, "undated.jsonl");
  writeFileSync(
    path,
    [
      { type: "message", message: { role: "user", content: "no timestamps here" } },
      { type: "message", message: { role: "assistant", content: "none at all" } },
    ]
      .map((line) => JSON.stringify(line))
      .join("\n"),
  );
  // frozenDeps' now is 2026-09-03, after the birth.
  assert.equal(backfillPiSessions(db, { sessionsDir, notBefore: BIRTH }, frozenDeps()), 1);
  assert.deepEqual(trackedSessions(db), [path]);
  db.close();
});

test("a floor that is not an instant is refused before any file is read", () => {
  const { db, dir } = fixture();
  assert.throws(
    () =>
      backfillPiSessions(
        db,
        { sessionsDir: PI_SESSIONS_DIR, notBefore: "yesterday" },
        frozenDeps(),
      ),
    /notBefore/,
  );
  assert.deepEqual(trackedSessions(db), []);
  db.close();
  void dir;
});

test("homeBornAt refuses a database with no migration ledger rows", () => {
  const { db } = fixture();
  db.exec("CREATE TABLE IF NOT EXISTS _migrations (id TEXT PRIMARY KEY, applied_at TEXT NOT NULL)");
  db.exec("DELETE FROM _migrations");
  assert.throws(() => homeBornAt(db), /_migrations/);
  db.close();
});
